    dict(slug='garbage-collection-pause', name='Garbage collection pause', cat='systems', aka=['GC pause', 'stop-the-world pause'],
         definition='A garbage collection pause is a period when a managed runtime such as the JVM, .NET or Go stops or slows application threads to reclaim unused memory, adding delay to the requests in progress.',
         why='GC pauses are a common cause of tail latency. Every request that happens to be in flight during a 300 ms pause gets 300 ms slower, so the problem shows up in p99, not in the average.',
         example='A Java service with a 4 GB heap has p50 of 30 ms and p99 of 450 ms. GC logs show G1 pauses of 200 to 400 ms every 20 s under load, caused by short-lived objects from building large JSON responses. Reducing that garbage brings p99 to 90 ms.',
         measure='Turn on GC logging (in Java, -Xlog:gc*), and line up pause times with latency spikes. Look at pause duration, frequency, time spent in GC as a share of total time, and heap after each collection.',
         mistakes=['Adding heap without looking at allocation rate, which can make pauses longer.',
                   'Tuning flags before measuring.'],
         related=['tail-latency', 'memory-leak', 'warm-up', 'flame-graph']),

